s.saveResult=async()=>{
  if(s.viewMode==='lookup'){field.notify('โหมดสืบค้นเป็นแบบอ่านอย่างเดียว','warning',3000);return;}
  const item=s.manual.item,order=s.manual.order,orderView=s.manual.orderView===true;
