  if(!s.reportSectionCode(order)){field.notify('ไม่พบ Section ของแถว Order จึงยกเลิกไม่ได้','warning',4500);return;}
  s.selected={};
  s.cancelDialog={...s.emptyCancelDialog(),visible:true,order:order};
